def next_in_series(seq):
    diffs = [seq[i+1]-seq[i] for i in range(len(seq)-1)]
    if len(set(diffs)) == 1:
        return seq[-1] + diffs[0]
    second_diff = [diffs[i+1]-diffs[i] for i in range(len(diffs)-1)]
    if len(set(second_diff)) == 1:
        return seq[-1] + diffs[-1] + second_diff[0]
    return seq[-1] + diffs[-1] + 1

