def find_words(board, words):
    trie = {}
    for w in words:
        node = trie
        for ch in w:
            node = node.setdefault(ch, {})
        node['#'] = w
    rows, cols = len(board), len(board[0])
    res = set()
    def dfs(r, c, node):
        if '#' in node:
            res.add(node['#'])
        ch = board[r][c]
        if ch not in node:
            return
        board[r][c] = ''
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                dfs(nr, nc, node[ch])
        board[r][c] = ch
    for r in range(rows):
        for c in range(cols):
            dfs(r, c, trie)
    return list(res)

