import sys

class TrieNode:
    def __init__(self):
        self.children = {}
        self.word = None

def build_trie(words):
    root = TrieNode()
    for w in words:
        node = root
        for c in w:
            if c not in node.children:
                node.children[c] = TrieNode()
            node = node.children[c]
        node.word = w
    return root

def main():
    data = sys.stdin.read().strip()
    parts = data.split("\n")
    board = eval(parts[0].split("=", 1)[1].strip())
    words = eval(parts[1].split("=", 1)[1].strip())
    root = build_trie(words)
    m, n = len(board), len(board[0])
    result = []
    def dfs(i, j, node):
        if i < 0 or i >= m or j < 0 or j >= n:
            return
        c = board[i][j]
        if c not in node.children:
            return
        next_node = node.children[c]
        if next_node.word:
            result.append(next_node.word)
            next_node.word = None
        board[i][j] = '#'
        dfs(i + 1, j, next_node)
        dfs(i - 1, j, next_node)
        dfs(i, j + 1, next_node)
        dfs(i, j - 1, next_node)
        board[i][j] = c
        if not next_node.children:
            del node.children[c]
    for i in range(m):
        for j in range(n):
            dfs(i, j, root)
    print(result)

main()

import sys, json

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

class WordDictionary:
    def __init__(self):
        self.root = TrieNode()
    def addWord(self, word):
        node = self.root
        for c in word:
            if c not in node.children:
                node.children[c] = TrieNode()
            node = node.children[c]
        node.is_end = True
    def search(self, word):
        def dfs(node, idx):
            if idx == len(word):
                return node.is_end
            c = word[idx]
            if c == '.':
                for child in node.children.values():
                    if dfs(child, idx + 1):
                        return True
                return False
            if c not in node.children:
                return False
            return dfs(node.children[c], idx + 1)
        return dfs(self.root, 0)

def main():
    data = sys.stdin.read().strip()
